WITH base AS (SELECT id, account_id, amount, txn_time, merchant, CASE WHEN merchant = 'Lazada' THEN 1 ELSE 0 END AS is_lazada FROM transactions WHERE txn_time >= TO_DATE('2023-11-08') AND merchant IS NOT NULL), remaining_keys AS (SELECT id, account_id FROM base INTERSECT SELECT id, account_id FROM transactions WHERE amount < 1600), reconciled AS (SELECT s.* FROM base s JOIN remaining_keys k ON s.id = k.id AND s.account_id = k.account_id), with_windows AS (SELECT *, DENSE_RANK() OVER (PARTITION BY merchant, account_id ORDER BY is_lazada NULLS FIRST) AS is_lazada_dense_rank, CUME_DIST() OVER (ORDER BY is_lazada DESC) AS is_lazada_cume_dist FROM reconciled), with_windows_transactions AS (SELECT *, RANK() OVER (PARTITION BY merchant ORDER BY is_lazada) AS is_lazada_rank, COUNT(is_lazada_cume_dist) OVER (PARTITION BY account_id ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS is_lazada_cume_dist_count_30d, MAX(is_lazada_cume_dist) OVER (PARTITION BY merchant ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS is_lazada_cume_dist_max_7d FROM with_windows), totals AS (SELECT CASE WHEN is_lazada_cume_dist >= 0.76 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_lazada_cume_dist_tier, MIN(txn_time) AS first_txn_time, ROUND(AVG(is_lazada), 2) AS avg_is_lazada, SIZE(COLLECT_SET(merchant)) AS num_merchants, COUNT_IF(merchant = 'Lazada') AS lazada_events FROM with_windows_transactions GROUP BY 1) SELECT is_lazada_cume_dist_tier, first_txn_time, avg_is_lazada, num_merchants, lazada_events FROM totals ORDER BY is_lazada_cume_dist_tier DESC, lazada_events LIMIT 20
